insert into public.ref_unit(unit_id, law_id, unit_path, unit_label, unit_type, article_no, display_text, source_version, metadata) values
  ('UNIT-0000581','LAW-0089','a2','제2조','article','2','제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2019.8.27, 2021.5.18, 2023.4.18, 2024.3.19, 2025.5.27, 2025.12.30>','adoms-graph-20260829','{"doc": "항공안전법"}'),
  ('UNIT-0004816','LAW-0075','a4/n2','제4조제2호','article','4','2.  「산업안전보건법」 제17조부터 제19조까지 및 제22조에 따라 두어야 하는 인력이 총 3명 이상이고 다음 각 목의 어느 하나에 해당하는 사업 또는 사업장인 경우에는 안전ㆍ보건에 관한 업무를 총괄ㆍ관리하는 전담 조직을 둘 것. 이 경우 나목에 해당하지 않던 건설사업자가 나목에 해당하게 된 경우에는 공시한 연도의 다음 연도 1월 1일까지 해당 조직을 두어야 한다.','adoms-graph-20260829','{"doc": "중대재해 처벌 등에 관한 법률 시행령"}'),
  ('UNIT-0006736','LAW-0097','a16','제16조','article','16','제16조(유해화학물질의 표시 등)','adoms-graph-20260829','{"doc": "화학물질관리법"}'),
  ('UNIT-0006837','LAW-0097','a23/p3','제23조제3항','article','23','③ 제1항에 따라 화학사고예방관리계획서를 제출한 자가 다음 각 호의 어느 하나에 해당하는 경우에는 기후에너지환경부령으로 정하는 바에 따라 변경된 화학사고예방관리계획서를 기후에너지환경부장관에게 제출하여야 한다. <개정 2025.10.1>','adoms-graph-20260829','{"doc": "화학물질관리법"}'),
  ('UNIT-0007366','LAW-0099','a12','제12조','article','12','제12조(유해화학물질관리자)','adoms-graph-20260829','{"doc": "화학물질관리법 시행령"}'),
  ('UNIT-0007707','LAW-0098','a19','제19조','article','19','제19조(화학사고예방관리계획서의 작성ㆍ제출)','adoms-graph-20260829','{"doc": "화학물질관리법 시행규칙"}'),
  ('UNIT-0008446','LAW-0005','a2','제2조','article','2','제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2015.5.18, 2015.7.24, 2018.8.14, 2019.4.30, 2020.2.18, 2021.3.16>','adoms-graph-20260829','{"doc": "건설기술 진흥법"}'),
  ('UNIT-0008887','LAW-0005','a62','제62조','article','62','제62조(건설공사의 안전관리)','adoms-graph-20260829','{"doc": "건설기술 진흥법"}'),
  ('UNIT-0010643','LAW-0005','a98','제98조','article','98','제98조(안전관리계획의 수립)','adoms-graph-20260829','{"doc": "건설기술 진흥법 시행령"}'),
  ('UNIT-0020408','LAW-0047','a7','제7조','article','7','제7조(시설물의 종류) 시설물의 종류는 다음 각 호와 같다.','adoms-graph-20260829','{"doc": "시설물의 안전 및 유지관리에 관한 특별법"}'),
  ('UNIT-0021190','LAW-0060','a20','제20조','article','20','제20조(위험물의 운반)','adoms-graph-20260829','{"doc": "위험물안전관리법"}'),
  ('UNIT-0021976','LAW-0009','a11g2','제11조의2','article','11','제11조의2(용기등의 표시) 용기등을 제조ㆍ수입하는 자(외국용기등 제조자를 포함한다)는 그 용기등에 제조일자, 제조자 등 산업통상부령으로 정하는 표시를 하여야 한다. <개정 2008.2.29, 2013.3.23, 2025.10.1>','adoms-graph-20260829','{"doc": "고압가스 안전관리법"}'),
  ('UNIT-0023505','LAW-0055','a10','제10조','article','10','제10조(연구실안전환경관리자의 지정)','adoms-graph-20260829','{"doc": "연구실 안전환경 조성에 관한 법률"}'),
  ('UNIT-0023510','LAW-0055','a10/p2','제10조제2항','article','10','② 연구주체의 장은 제1항에 따라 연구실안전환경관리자를 지정할 때 대학ㆍ연구기관등의 분교 또는 분원이 있는 경우에는 분교 또는 분원에 별도로 연구실안전환경관리자를 지정하여야 한다. 다만, 분교 또는 분원의 연구활동종사자 총 인원이 10명 미만에 해당하는 등 대통령령으로 정하는 경우에는 별도로 연구실안전환경관리자를 지정하지 아니할 수 있다.','adoms-graph-20260829','{"doc": "연구실 안전환경 조성에 관한 법률"}'),
  ('UNIT-0023885','LAW-0057','a16','제16조','article','16','제16조(연구활동종사자 등에 대한 교육ㆍ훈련)','adoms-graph-20260829','{"doc": "연구실 안전환경 조성에 관한 법률 시행령"}'),
  ('UNIT-0024073','LAW-0057','a8','제8조','article','8','제8조(연구실안전환경관리자 지정 및 업무 등)','adoms-graph-20260829','{"doc": "연구실 안전환경 조성에 관한 법률 시행령"}'),
  ('UNIT-0024074','LAW-0055','a8/p1','제8조제1항','article','8','① 연구주체의 장은 해당 대학ㆍ연구기관등의 상시 연구활동종사자가 300명 이상이거나 연구활동종사자(상시 연구활동종사자를 포함한다)가 1,000명 이상인 경우에는 법 제10조제1항에 따라 지정된 연구실안전환경관리자 중 1명 이상에게 제4항에 따른 업무만을 전담하도록 해야 한다.','adoms-graph-20260829','{"doc": "연구실 안전환경 조성에 관한 법률 시행령"}'),
  ('UNIT-0024201','LAW-0056','a5','제5조','article','5','제5조(연구실안전관리위원회의 구성 및 운영)','adoms-graph-20260829','{"doc": "연구실 안전환경 조성에 관한 법률 시행규칙"}'),
  ('UNIT-0026331','LAW-0014','a17','제17조','article','17','제17조(광산안전도의 작성) 광업권자나 조광권자는 산업통상부령으로 정하는 바에 따라 광산안전도(鑛山安全圖)를 작성하여 광산사무소에 갖추어 두고, 그 부본(副本)을 산업통상부장관에게 제출하여야 한다. <개정 2013.3.23, 2016.1.6, 2025.10.1>','adoms-graph-20260829','{"doc": "광산안전법"}'),
  ('UNIT-0026404','LAW-0014','a5','제5조','article','5','제5조(광업권자 또는 조광권자의 의무)','adoms-graph-20260829','{"doc": "광산안전법"}'),
  ('UNIT-0026626','LAW-0014','a5/p1','제5조제1항','article','5','① 법 제5조제1항제5호에 따라 30명 이상의 광산근로자가 종사하는 광산의 광업권자 또는 조광권자는 광산구호대를 조직ㆍ운영하여야 한다.','adoms-graph-20260829','{"doc": "광산안전법 시행령"}'),
  ('UNIT-0026849','LAW-0014','a30/p1','제30조제1항','article','30','① 광업권자 또는 조광권자는 법 제17조에 따라 매년 12월 31일 현재의 광산안전도 3부 또는 전자도면을 작성하여 다음 해 1월 31일까지 사무소장에게 제출하여야 한다. 다만, 상시 광산근로자를 10명 이하로 고용하는 노천채굴광산으로서 사무소장이 안전상 지장이 없다고 인정하는 경우에는 광산안전도를 제출하지 아니할 수 있다.','adoms-graph-20260829','{"doc": "광산안전법 시행규칙"}'),
  ('UNIT-0027901','LAW-0058','a26/p3','제26조제3항','article','26','③ 발전용원자로운영자는 원자로마다 제84조에 따라 원자로조종감독자면허를 받은 사람 및 원자로조종사면허를 받은 사람 각 1명 이상을 늘 원자로의 운전업무에 종사하게 하여야 한다.','adoms-graph-20260829','{"doc": "원자력안전법"}'),
  ('UNIT-0027902','LAW-0058','a26/p4','제26조제4항','article','26','④ 발전용원자로운영자는 제84조에 따른 핵연료물질취급감독자면허를 받은 사람 및 방사선취급감독자면허를 받은 사람 각 1명 이상을 원자로 및 관계시설에서의 핵물질 및 방사선안전관리를 위한 업무에 종사하게 하여야 한다.','adoms-graph-20260829','{"doc": "원자력안전법"}'),
  ('UNIT-0031548','LAW-0028','a115','제115조','article','115','제115조(물질안전보건자료대상물질 용기 등의 경고표시)','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0031614','LAW-0028','a125','제125조','article','125','제125조(작업환경측정)','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032064','LAW-0028','a18','제18조','article','18','제18조(보건관리자)','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032070','LAW-0028','a19','제19조','article','19','제19조(안전보건관리담당자)','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032075','LAW-0028','a2','제2조','article','2','제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2020.5.26, 2023.8.8>','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032218','LAW-0028','a39/p1','제39조제1항','article','39','① 사업주는 다음 각 호의 어느 하나에 해당하는 건강장해를 예방하기 위하여 필요한 조치(이하 "보건조치"라 한다)를 하여야 한다. <개정 2024.10.22>','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032244','LAW-0028','a42','제42조','article','42','제42조(유해위험방지계획서의 작성ㆍ제출 등)','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032245','LAW-0028','a42/p1','제42조제1항','article','42','① 사업주는 다음 각 호의 어느 하나에 해당하는 경우에는 이 법 또는 이 법에 따른 명령에서 정하는 유해ㆍ위험 방지에 관한 사항을 적은 계획서(이하 "유해위험방지계획서"라 한다)를 작성하여 고용노동부령으로 정하는 바에 따라 고용노동부장관에게 제출하고 심사를 받아야 한다. 다만, 제3호에 해당하는 사업주 중 산업재해발생률 등을 고려하여 고용노동부령으로 정하는 기준에 해당하는 사업주는 유해위험방지계획서를 스스로 심사하고, 그 심사결과서를 작성하여 고용노동부장관에게 제출하여야 한다. <개정 2020.5.26>','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032416','LAW-0028','a70/p1','제70조제1항','article','70','① 건설공사발주자는 다음 각 호의 어느 하나에 해당하는 사유로 건설공사가 지연되어 해당 건설공사도급인이 산업재해 예방을 위하여 공사기간의 연장을 요청하는 경우에는 특별한 사유가 없으면 공사기간을 연장하여야 한다.','adoms-graph-20260829','{"doc": "산업안전보건법"}'),
  ('UNIT-0032906','LAW-0028','a24/p1','제24조제1항','article','24','① 다음 각 호의 어느 하나에 해당하는 사업의 사업주는 법 제19조제1항에 따라 상시근로자 20명 이상 50명 미만인 사업장에 안전보건관리담당자를 1명 이상 선임해야 한다.','adoms-graph-20260829','{"doc": "산업안전보건법 시행령"}'),
  ('UNIT-0033043','LAW-0030','a42','제42조','article','42','제42조(유해위험방지계획서 제출 대상)','adoms-graph-20260829','{"doc": "산업안전보건법 시행령"}'),
  ('UNIT-0033195','LAW-0030','a59','제59조','article','59','제59조(기술지도계약 체결 대상 건설공사 및 체결 시기)','adoms-graph-20260829','{"doc": "산업안전보건법 시행령"}'),
  ('UNIT-0033595','LAW-0028','a104','제104조','article','104','제104조(대여 공장건축물에 대한 조치) 공용으로 사용하는 공장건축물로서 다음 각 호의 어느 하나의 장치가 설치된 것을 대여하는 자는 해당 건축물을 대여받은 자가 2명 이상인 경우로서 다음 각 호의 어느 하나의 장치의 전부 또는 일부를 공용으로 사용하는 경우에는 그 공용부분의 기능이 유효하게 작동되도록 하기 위하여 점검ㆍ보수 등 필요한 조치를 해야 한다.','adoms-graph-20260829','{"doc": "산업안전보건법 시행규칙"}'),
  ('UNIT-0034061','LAW-0028','a170/p1','제170조제1항','article','170','① 물질안전보건자료대상물질을 양도하거나 제공하는 자 또는 이를 사업장에서 취급하는 사업주가 법 제115조제1항 및 제2항에 따른 경고표시를 하는 경우에는 물질안전보건자료대상물질 단위로 경고표지를 작성하여 물질안전보건자료대상물질을 담은 용기 및 포장에 붙이거나 인쇄하는 등 유해ㆍ위험정보가 명확히 나타나도록 해야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 표시를 한 경우에는 경고표시를 한 것으로 본다.','adoms-graph-20260829','{"doc": "산업안전보건법 시행규칙"}'),
  ('UNIT-0034686','LAW-0029','a42','제42조','article','42','제42조(제출서류 등)','adoms-graph-20260829','{"doc": "산업안전보건법 시행규칙"}'),
  ('UNIT-0034970','LAW-0029','a86','제86조','article','86','제86조(기본안전보건대장 등)','adoms-graph-20260829','{"doc": "산업안전보건법 시행규칙"}'),
  ('UNIT-0034989','LAW-0029','a87','제87조','article','87','제87조(공사기간 연장 요청 등)','adoms-graph-20260829','{"doc": "산업안전보건법 시행규칙"}'),
  ('UNIT-0035409','LAW-0028','a19','제19조','article','19','제19조(경보용 설비 등) 사업주는 연면적이 400제곱미터 이상이거나 상시 50명 이상의 근로자가 작업하는 옥내작업장에는 비상시에 근로자에게 신속하게 알리기 위한 경보용 설비 또는 기구를 설치하여야 한다.','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0035569','LAW-0028','a23/n5','제23조제5호','article','23','5.  수직갱에 가설된 통로의 길이가 15미터 이상인 경우에는 10미터 이내마다 계단참을 설치할 것','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0035626','LAW-0028','a24/p1/n8','제24조제1항제8호','article','24','8.  사다리식 통로의 길이가 10미터 이상인 경우에는 5미터 이내마다 계단참을 설치할 것','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0035627','LAW-0028','a24/p1/n9','제24조제1항제9호','article','24','9.  사다리식 통로의 기울기는 75도 이하로 할 것. 다만, 고정식 사다리식 통로의 기울기는 90도 이하로 하고, 그 높이가 7미터 이상인 경우에는 다음 각 목의 구분에 따른 조치를 할 것','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0036002','LAW-0028','a32/p1','제32조제1항','article','32','① 사업주는 다음 각 호의 어느 하나에 해당하는 작업을 하는 근로자에 대해서는 다음 각 호의 구분에 따라 그 작업조건에 맞는 보호구를 작업하는 근로자 수 이상으로 지급하고 착용하도록 하여야 한다. <개정 2017.3.3, 2024.6.28>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0036288','LAW-0028','a38/p1','제38조제1항','article','38','① 사업주는 다음 각 호의 작업을 하는 경우 근로자의 위험을 방지하기 위하여 별표 4에 따라 해당 작업, 작업장의 지형ㆍ지반 및 지층 상태 등에 대한 사전조사를 하고 그 결과를 기록ㆍ보존해야 하며, 조사결과를 고려하여 별표 4의 구분에 따른 사항을 포함한 작업계획서를 작성하고 그 계획에 따라 작업을 하도록 해야 한다. <개정 2023.11.14>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0036442','LAW-0028','a42/p4/n6','제42조제4항제6호','article','42','6.  안전모를 착용하되, 작업 높이가 2미터 이상인 경우에는 안전모와 안전대를 함께 착용할 것','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0036912','LAW-0028','a517','제517조','article','517','제517조(청력보존 프로그램 시행 등) 사업주는 다음 각 호의 어느 하나에 해당하는 경우에 청력보존 프로그램을 수립하여 시행해야 한다. <개정 2019.12.26, 2021.11.19, 2024.6.28>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0036944','LAW-0028','a524/p1','제524조제1항','article','524','① 사업주는 기압조절실의 바닥면적과 공기의 부피를 그 기압조절실에서 가압이나 감압을 받는 근로자 1인당 각각 0.3제곱미터 이상 및 0.6세제곱미터 이상이 되도록 하여야 한다.','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0036963','LAW-0028','a53','제53조','article','53','제53조(계측장치의 설치 등) 사업주는 다음 각 호의 어느 하나에 해당하는 경우에는 그에 필요한 계측장치를 설치하여 계측결과를 확인하고 그 결과를 통하여 안전성을 검토하는 등 위험을 방지하기 위한 조치를 해야 한다. <개정 2024.6.28>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0037042','LAW-0028','a547/p1','제547조제1항','article','547','① 사업주는 근로자가 표면공급식 잠수작업을 하는 경우 잠수작업자가 1명인 경우에는 감시인을 1명 배치하고, 잠수작업자가 2명 이상인 경우에는 감시인 1명당 잠수작업자가 2명을 초과하지 않도록 감시인을 배치해야 한다. <개정 2024.6.28>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0037296','LAW-0027','a593','제593조','article','593','제593조(적용 범위) 이 장의 규정은 근로자가 세균ㆍ바이러스ㆍ곰팡이 등 법 제39조제1항제1호에 따른 병원체에 노출될 위험이 있는 다음 각 호의 작업을 하는 사업 또는 사업장에 대하여 적용한다. <개정 2019.12.26>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0037424','LAW-0028','a616','제616조','article','616','제616조(호흡기보호 프로그램 시행 등) 사업주는 다음 각 호의 어느 하나에 해당하는 경우에 호흡기보호 프로그램을 수립하여 시행하여야 한다. <개정 2019.12.26>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0037653','LAW-0028','a662/p1','제662조제1항','article','662','① 사업주는 다음 각 호의 어느 하나에 해당하는 경우에 근골격계질환 예방관리 프로그램을 수립하여 시행하여야 한다. <개정 2017.3.3>','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0037788','LAW-0028','a79g2','제79조의2','article','79','제79조의2(세척시설 등) 사업주는 근로자로 하여금 다음 각 호의 어느 하나에 해당하는 업무에 상시적으로 종사하도록 하는 경우 근로자가 접근하기 쉬운 장소에 세면ㆍ목욕시설, 탈의 및 세탁시설을 설치하고 필요한 용품과 용구를 갖추어 두어야 한다.','adoms-graph-20260829','{"doc": "산업안전보건기준에 관한 규칙"}'),
  ('UNIT-0042351','LAW-0012','a2','제2조','article','2','제2조(정의) 이 법에서 사용하는 용어의 뜻은 다음과 같다. <개정 2024.2.13, 2025.8.26>','adoms-graph-20260829','{"doc": "공항시설법"}'),
  ('UNIT-0042506','LAW-0012','a31g5','제31조의5','article','31','제31조의5(조류충돌 예방 전담인력ㆍ장비 운용)','adoms-graph-20260829','{"doc": "공항시설법"}'),
  ('UNIT-0043580','LAW-0012','a19g6/p1','제19조의6제1항','article','19','① 법 제31조의5제1항에 따라 공항운영자는 공항 운영시간, 활주로 수, 항공기 운항횟수 등을 고려하여 조류충돌 예방 업무를 상시적으로 수행하는 전담인력을 4명 이상 확보해야 한다.','adoms-graph-20260829','{"doc": "공항시설법 시행규칙"}'),
  ('UNIT-0044725','LAW-0078','a3','제3조','article','3','제3조(정의) 이 법에서 사용하는 용어의 정의는 다음 각호와 같다. <개정 2020.6.9>','adoms-graph-20260829','{"doc": "철도산업발전기본법"}'),
  ('UNIT-0047682','LAW-0023','a33/p1','제33조제1항','article','33','① 4명 이상의 마약류취급의료업자가 의료에 종사하는 의료기관의 대표자는 그 의료기관에 마약류관리자를 두어야 한다. 다만, 향정신성의약품만을 취급하는 의료기관의 경우에는 그러하지 아니하다.','adoms-graph-20260829','{"doc": "마약류 관리에 관한 법률"}'),
  ('UNIT-0051005','LAW-0065','a6','제6조','article','6','제6조(제조업의 허가 등)','adoms-graph-20260829','{"doc": "의료기기법"}'),
  ('UNIT-0051288','LAW-0065','a11/p1','제11조제1항','article','11','① 법 제6조제1항에 따라 제조업허가를 받으려는 자는 제조소마다 1명 이상의 품질책임자를 두어야 한다.','adoms-graph-20260829','{"doc": "의료기기법 시행규칙"}'),
  ('UNIT-0051306','LAW-0065','a11/p3','제11조제3항','article','11','③ 제1항에 따라 제조업자가 2명 이상의 품질책임자를 두는 경우에는 품질책임자의 업무를 분장하여 품질책임자 각자가 가지는 책임의 한계를 명확하게 하여야 한다.','adoms-graph-20260829','{"doc": "의료기기법 시행규칙"}'),
  ('UNIT-0062263','LAW-0050','a16g2/p1','제16조의2제1항','article','16','① 시ㆍ도지사, 대도시의 장 및 시장ㆍ군수ㆍ구청장은 악취로 인한 주민의 건강상 위해(危害)를 예방하고 생활환경을 보전하기 위하여 해당 지방자치단체의 장이 설치ㆍ운영하는 다음 각 호의 악취배출시설에 대하여 5년마다 기술진단을 실시하여야 한다. 다만, 다른 법률에 따라 악취에 관한 기술진단을 실시한 경우에는 이 항에 따른 기술진단을 실시한 것으로 본다. <개정 2016.1.27, 2017.1.17, 2023.3.28, 2025.10.1>','adoms-graph-20260829','{"doc": "악취방지법"}'),
  ('UNIT-0062602','LAW-0051','a13g2','제13조의2','article','13','제13조의2(기술진단)','adoms-graph-20260829','{"doc": "악취방지법 시행규칙"}'),
  ('UNIT-0070380','LAW-0069','a15','제15조','article','15','제15조(배출시설의 설치기준) 다음 각 호의 어느 하나에 해당하는 허가나 승인을 받거나 신고를 하려는 자는 해당 법률에서 정하는 시설기준 외에 제14조에 따른 배출허용기준(이하 "배출허용기준"이라 한다)을 충족할 수 있도록 시설을 갖추어야 한다. <개정 2007.4.11, 2007.4.27, 2012.2.1, 2017.1.17, 2020.5.26>','adoms-graph-20260829','{"doc": "잔류성오염물질 관리법"}'),
  ('UNIT-0079305','LAW-0091','a32/p1','제32조제1항','article','32','①해양수산부령으로 정하는 선박의 소유자는 그 선박에 승무하는 선원 중에서 선장을 보좌하여 선박으로부터의 오염물질 및 대기오염물질의 배출방지에 관한 업무를 관리하게 하기 위하여 대통령령으로 정하는 자격을 갖춘 사람을 해양오염방지관리인으로 임명ㆍ보유하여야 한다. 이 경우 유해액체물질을 산적하여 운반하는 선박의 경우에는 유해액체물질의 해양오염방지관리인 1명 이상을 추가로 임명ㆍ보유하여야 한다. <개정 2008.2.29, 2013.3.23, 2020.3.24, 2025.12.30>','adoms-graph-20260829','{"doc": "해양환경관리법"}'),
  ('UNIT-0079917','LAW-0092','a39','제39조','article','39','제39조(선박 해양오염방지관리인의 자격ㆍ업무내용 등)','adoms-graph-20260829','{"doc": "해양환경관리법 시행령"}'),
