-- ADOMS 지식그래프 → 용인시 데모 시드
-- 생성 2026-08-29 · 원천 GraphDB adoms_v1 (triple 10,421,038)
-- 001_demo_schema.sql 적용 후 실행하십시오. seed.sql 과 같은 자리를 씁니다.
--
-- ★ ID 는 ADOMS 그래프 ID 를 그대로 씁니다 (OBL-… · UNIT-…).
--   나중에 그래프로 되돌아갈 때 조인이 그냥 됩니다.
--
-- ★ 검수 상태를 반드시 함께 보십시오 —
--   ref_obligation.review_status 가 'approved' 인 것은 사람이 확인한 것입니다.
--   나머지는 기계 판정입니다. 화면에 「법적 확정」으로 표시하지 마십시오.
--
-- ★ ref_rule 에는 「적용 조건」만 넣었습니다.
--   「높이 3미터 이상 장소에서 투하」 같은 **이행 방법**은 적용 조건이 아니므로 뺐습니다.
--   그것을 규칙으로 넣으면 매칭이 엉뚱해집니다. 제외 내역은 파일 끝 주석에 있습니다.

begin;

-- ═══ 법령 104 ═══
on conflict (law_id) do update set title_ko=excluded.title_ko, source_version=excluded.source_version;

-- ═══ 조문 304 ═══  display_text 는 법령 원문입니다 (정본과 글자 단위 일치)
on conflict (unit_id) do update set display_text=excluded.display_text, unit_path=excluded.unit_path;

-- ═══ 의무 216 ═══
on conflict (obl_id) do update set title_ko=excluded.title_ko, anchor_unit_id=excluded.anchor_unit_id, metadata=excluded.metadata;

-- ═══ 적용 규칙 128 ═══  등급이 「적용조건」·「적용조건후보」인 것만
on conflict (rul_id) do update set demo_approved=excluded.demo_approved, review_status=excluded.review_status, source_quote=excluded.source_quote;

-- ═══ 규칙 ↔ 의무 128 ═══
-- ★ link_basis='same_unit' — 규칙과 의무가 **같은 앵커 조문**을 공유합니다.
--   정본에 직접 연결이 아직 없어 조문을 경유해 이었습니다. 그쪽 seed.sql 의
--   'same_unit' 과 같은 뜻이며, 'manual_review'(사람 확인)보다 약한 근거입니다.
on conflict (rul_id, obl_id) do update set link_confidence=excluded.link_confidence, demo_approved=excluded.demo_approved;

commit;

-- ─────────────────────────────────────────────────────────
-- 제외한 것
--   불명              43건
--   이행기준            10건
--
--   「이행기준」은 「높이 3미터 이상인 장소로부터 물체를 투하」 같은 것입니다.
--   그 의무가 **걸리는 조건**이 아니라 **이행 방법**이므로 규칙이 아닙니다.
--   「불명」은 원문만으로 어느 쪽인지 가릴 수 없던 것입니다.
--
-- 데이터 성격
--   법령 원문(ref_unit.display_text)  정본과 글자 단위 일치 — 표본 889건 불일치 0
--   의무 판정                        사람 검수 6.7%
--   의무 → 중처법 확보의무 편입         전건 (metadata.securing)
-- ─────────────────────────────────────────────────────────